import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const d=JSON.parse('{"title":"AI 动态 · 2026-07-29","description":"","frontmatter":{"title":"AI 动态 · 2026-07-29","date":"2026-07-29T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-07/ai-news-2026-07-29.md","filePath":"news/2026-07/ai-news-2026-07-29.md","lastUpdated":1786092171000}'),s={name:"news/2026-07/ai-news-2026-07-29.md"};function i(o,a,l,c,p,h){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="ai-动态-·-2026-07-29" tabindex="-1">AI 动态 · 2026-07-29 <a class="header-anchor" href="#ai-动态-·-2026-07-29" aria-label="Permalink to &quot;AI 动态 · 2026-07-29&quot;">​</a></h1><blockquote><p>截至 2026-07-29。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="九章云极alaya-token完成kimi-k3适配-全球首个开源3t级模型入驻token工厂" tabindex="-1">九章云极Alaya Token完成Kimi K3适配，全球首个开源3T级模型入驻Token工厂 <a class="header-anchor" href="#九章云极alaya-token完成kimi-k3适配-全球首个开源3t级模型入驻token工厂" aria-label="Permalink to &quot;九章云极Alaya Token完成Kimi K3适配，全球首个开源3T级模型入驻Token工厂&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-29">2026-07-29</time></p><p>九章云极DataCanvas旗下Token交付平台Alaya Token正式完成对Kimi K3的适配与上线。Kimi K3是全球首个开源3万亿参数级大模型，采用KDA混合线性注意力机制，在Frontend Code Arena以1679分位列全球第一。Alaya Token构建“聚合而不锁定”的模型服务生态，企业可一套密钥在多模型间自由切换。对读者：若企业需多模型灵活调用，Alaya Token的“按需付费”模式可降低算力采购锁定风险。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/462058.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="周鸿祎发布纳米work-新一代企业智能体工作平台" tabindex="-1">周鸿祎发布纳米Work：新一代企业智能体工作平台 <a class="header-anchor" href="#周鸿祎发布纳米work-新一代企业智能体工作平台" aria-label="Permalink to &quot;周鸿祎发布纳米Work：新一代企业智能体工作平台&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-29">2026-07-29</time></p><p>360集团创始人周鸿祎发布企业智能体工作平台“纳米Work”，面向企业老板、创业者及员工打造超级组织。平台内置多智能体引擎、多模型底座、云端办公室等五大能力体系，并融入原生安全设计。周鸿祎宣布为首批用户提供每人1亿Token试用额度，计划帮助1000家小企业完成AI落地。对读者：中小企业可关注其低门槛智能体协作能力，但需评估长程任务Token消耗与安全边界。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/462062.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="首个鸿蒙pc开源ai统一工作台jiuwenswarm发布" tabindex="-1">首个鸿蒙PC开源AI统一工作台JiuwenSwarm发布 <a class="header-anchor" href="#首个鸿蒙pc开源ai统一工作台jiuwenswarm发布" aria-label="Permalink to &quot;首个鸿蒙PC开源AI统一工作台JiuwenSwarm发布&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-29">2026-07-29</time></p><p>华为联合团队推出JiuwenSwarm蜂群智能体鸿蒙PC版本，为首个面向鸿蒙PC的开源AI统一工作台。该平台支持多智能体协同办公与编程，20分钟内可生成200页PPT，并引入人机协同新范式HITS，支持多人多机协同。JiuwenSwarm还能与飞书、小艺等场景联动，实现跨设备任务推进。对读者：鸿蒙生态开发者可关注其开源架构，探索多Agent协同工程在桌面端的落地潜力。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/462065.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="萝卜快跑抢跑无人车右舵-香港率先全无人-伦敦直面waymo" tabindex="-1">萝卜快跑抢跑无人车右舵：香港率先全无人，伦敦直面Waymo <a class="header-anchor" href="#萝卜快跑抢跑无人车右舵-香港率先全无人-伦敦直面waymo" aria-label="Permalink to &quot;萝卜快跑抢跑无人车右舵：香港率先全无人，伦敦直面Waymo&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-29">2026-07-29</time></p><p>百度萝卜快跑获香港运输署批准，在机场岛开展车内无安全员的全无人测试，为全球右舵市场首次。同时，萝卜快跑携手Uber和Freenow在伦敦启动公开道路测试，成为唯一明确进入伦敦Robotaxi测试体系的中国企业，将与Waymo在同一监管环境下竞速。对读者：关注自动驾驶出海的企业应留意右舵市场技术壁垒与海外监管合规要求。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/462071.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="美团发布全场景ai-agent平台catpaw" tabindex="-1">美团发布全场景AI Agent平台CatPaw <a class="header-anchor" href="#美团发布全场景ai-agent平台catpaw" aria-label="Permalink to &quot;美团发布全场景AI Agent平台CatPaw&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-07-29">2026-07-29</time></p><p><img src="https://rssfile.sspai.com/28/07/2026/article/d1a902c3-dbfb-33d8-9dbb-ec5871235d00.jpeg?imageMogr2/auto-orient/format/webp/ignore-error/1" alt="配图"></p><p>美团正式上线全场景AI Agent平台CatPaw，提供独立移动端App与PC客户端，双端任务实时同步。CatPaw支持7×24小时云端运行，即使本地设备关机也不受影响。平台融入美团本地生活领域行业认知，覆盖门店评价诊断、商品文案生成、营销活动策划等场景，支持多Agent并发处理与分级权限管控。对读者：本地生活从业者可关注其即装即用的专家技能，快速实现经营数据分析与营销自动化。</p><p class="news-entry-source"><a href="https://sspai.com/post/112837" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ia-writer-8-0大版本更新-不聊ai-聚焦搜索与写作流程重构" tabindex="-1">iA Writer 8.0大版本更新：不聊AI，聚焦搜索与写作流程重构 <a class="header-anchor" href="#ia-writer-8-0大版本更新-不聊ai-聚焦搜索与写作流程重构" aria-label="Permalink to &quot;iA Writer 8.0大版本更新：不聊AI，聚焦搜索与写作流程重构&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">少数派</span><time datetime="2026-07-29">2026-07-29</time></p><p><img src="https://rssfile.sspai.com/2026/07/27/68ee5b98153025cca0650740c1e4f515.png?imageMogr2/auto-orient/ignore-error/1" alt="配图"></p><p>老牌写作工具iA Writer发布8.0大版本更新，未跟风AI热潮，而是将全局搜索功能与单篇文章大纲功能整合，实现“大纲级搜索”。用户可在写作过程中直接搜索并定位至具体段落，无需中断当前任务。iA Writer此前在7.0版本中引入标注AI生成内容的功能，持续强调人类写作与AI写作的区分。对读者：追求专注写作体验的用户可升级体验其搜索整合功能，提升长文档回溯效率。</p><p class="news-entry-source"><a href="https://sspai.com/post/112787" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="kimi-k3正式开源-anthropic微妙表态-从未主张禁止开放权重模型" tabindex="-1">Kimi K3正式开源，Anthropic微妙表态：从未主张禁止开放权重模型 <a class="header-anchor" href="#kimi-k3正式开源-anthropic微妙表态-从未主张禁止开放权重模型" aria-label="Permalink to &quot;Kimi K3正式开源，Anthropic微妙表态：从未主张禁止开放权重模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-29">2026-07-29</time></p><p><img src="https://static001.infoq.cn/resource/image/62/6c/621dd93797d582f6eca7234813d03e6c.jpg" alt="配图"></p><p>月之暗面正式开源K3模型权重与技术报告，该模型为全球首个开源3万亿参数级大模型，采用KDA混合线性注意力机制，在Frontend Code Arena位列全球第一。Anthropic CEO Amodei同步回应称从未主张禁止开放权重模型，但强调对高能力模型的安全管控，担忧模型被滥用于网络攻击或生物攻击。对读者：开源模型能力持续突破，开发者可评估K3在编程与Agent场景的部署成本，同时关注地缘政治驱动的安全治理动态。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/jZ394NO5PIZIqNVbN4mD?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="moonshotai-flashkda-高性能kimi-delta-attention内核开源" tabindex="-1">MoonshotAI/FlashKDA：高性能Kimi Delta Attention内核开源 <a class="header-anchor" href="#moonshotai-flashkda-高性能kimi-delta-attention内核开源" aria-label="Permalink to &quot;MoonshotAI/FlashKDA：高性能Kimi Delta Attention内核开源&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MoonshotAI/FlashKDA</span><time datetime="2026-07-29">2026-07-29</time></p><p><img src="https://opengraph.githubassets.com/1/MoonshotAI/FlashKDA" alt="配图"></p><p>月之暗面开源FlashKDA项目，提供高性能Kimi Delta Attention内核实现。该项目针对K3模型自研的KDA混合线性注意力机制进行优化，可显著提升长上下文场景下的推理效率。对读者：关注大模型推理优化的开发者可研究其内核实现，探索在自有模型或应用中集成Delta Attention以降低长序列计算成本。</p><p class="news-entry-source"><a href="https://github.com/MoonshotAI/FlashKDA" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const w=e(s,[["render",i]]);export{d as __pageData,w as default};
